def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    # Mark the background connected to the outside.
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h-1 or c == 0 or c == w-1) and grid[r][c] == bg:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c = q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == bg:
                seen.add((nr,nc)); q.append((nr,nc))
    # Enclosed background regions are cavities: odd-sided cavities become 7,
    # even-sided cavities become 2.
    done = set(seen)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in done:
                continue
            q = deque([(r,c)]); done.add((r,c)); cells=[]
            while q:
                rr,cc=q.popleft(); cells.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in done and grid[nr][nc] == bg:
                        done.add((nr,nc)); q.append((nr,nc))
            minr=min(x for x,y in cells); maxr=max(x for x,y in cells)
            minc=min(y for x,y in cells); maxc=max(y for x,y in cells)
            color = 7 if (maxr-minr+1) % 2 == 1 and (maxc-minc+1) % 2 == 1 else 2
            for rr,cc in cells:
                out[rr][cc] = color
    return out
